"use client"

import * as React from "react"

import { type SegmentInteraction } from "@/lib/segment-interaction"
import { segmentsPageCount, toSegments, type Segment } from "@/lib/segments"
import { PageRibbon } from "@/components/ui/page-ribbon"
import { PdfViewer, type PdfViewerSlots } from "@/components/ui/pdf-viewer"
import {
  SegmentLegend,
  type SegmentLegendOrientation,
  type SegmentLegendSide,
  type SegmentLegendVariant,
} from "@/components/ui/segment-legend"
import { useSegmentInteraction } from "@/components/ui/use-segment-interaction"

const PDF_URL = "/samples/attention.pdf"

// The same split result the standalone Split Viewer block uses, over attention.pdf.
const SPLIT_OUTPUT = [
  { name: "Title & Abstract", pages: [1] },
  { name: "Introduction", pages: [2, 3] },
  { name: "Model Architecture", pages: [4, 5, 6] },
  { name: "Results", pages: [7, 8, 9] },
  { name: "References", pages: [10, 11] },
  { name: "Attention Visualizations", pages: [12, 13, 14, 15] },
]

type LegendSlot = "top" | "overlay" | "right"

type Preset = {
  label: string
  variant: SegmentLegendVariant
  orientation: SegmentLegendOrientation
  side?: SegmentLegendSide
  slot: LegendSlot
}

// Every way the legend can sit on the document. The page ribbon stays the left
// rail throughout; the legend takes the top, floats over the page, or runs down
// the right edge — so each is independent of the ribbon.
const PRESETS: Preset[] = [
  {
    label: "Bar",
    variant: "bar",
    orientation: "horizontal",
    side: "top",
    slot: "top",
  },
  {
    label: "Floating",
    variant: "floating",
    orientation: "horizontal",
    side: "top",
    slot: "overlay",
  },
  { label: "Rail", variant: "plain", orientation: "vertical", slot: "right" },
]

/**
 * The split viewer shown with every legend variant — a 2×2 gallery over one
 * `attention.pdf` split result. Each cell is a real `PdfViewer` with the page
 * ribbon as a left rail and the `SegmentLegend` placed a different way; one
 * shared selection dims the matching pages across all four at once.
 */
export function LegendVariantsBlock({ columns = 1 }: { columns?: 1 | 3 } = {}) {
  const segments = React.useMemo(() => toSegments(SPLIT_OUTPUT), [])
  const pageCount = React.useMemo(() => segmentsPageCount(segments), [segments])
  const interaction = useSegmentInteraction()

  return (
    <div className="flex h-full min-h-[680px] flex-col bg-background">
      <div className="border-b px-6 py-3">
        <h2 className="text-base font-semibold">
          Split viewer · legend variants
        </h2>
        <p className="mt-0.5 text-sm text-muted-foreground">
          One split result, three legend placements — bar, floating, and a
          vertical rail.
        </p>
      </div>
      <div className="min-h-0 flex-1 overflow-auto p-4">
        <div
          className={
            columns === 3
              ? "flex h-full min-h-0 flex-col gap-4 lg:flex-row"
              : "flex h-full min-h-0 flex-col gap-4"
          }
        >
          {PRESETS.map((preset) => (
            <Cell
              key={preset.label}
              preset={preset}
              segments={segments}
              pageCount={pageCount}
              interaction={interaction}
            />
          ))}
        </div>
      </div>
    </div>
  )
}

function Cell({
  preset,
  segments,
  pageCount,
  interaction,
}: {
  preset: Preset
  segments: Segment[]
  pageCount: number
  interaction: SegmentInteraction
}) {
  const [currentPage, setCurrentPage] = React.useState<number | null>(1)
  const panelRef = React.useRef<HTMLDivElement | null>(null)

  const jumpToPage = React.useCallback((page: number) => {
    panelRef.current
      ?.querySelector<HTMLElement>(`[data-page-number="${page}"]`)
      ?.scrollIntoView({ behavior: "smooth", block: "start" })
  }, [])

  const onSelect = (segment: Segment) => {
    if (segment.pages.length) jumpToPage(segment.pages[0])
  }

  const legend = (
    <SegmentLegend
      segments={segments}
      variant={preset.variant}
      orientation={preset.orientation}
      side={preset.side}
      density="compact"
      columns={preset.orientation === "horizontal" ? 2 : undefined}
      interaction={interaction}
      currentPage={currentPage}
      onSelect={onSelect}
    />
  )

  const ribbon = (
    <div className="h-full overflow-auto border-r border-border bg-background px-2 py-4">
      <PageRibbon
        orientation="vertical"
        rows={[{ id: "split", segments }]}
        pageCount={pageCount}
        currentPage={currentPage}
        interaction={interaction}
        onSelectPage={jumpToPage}
        showTicks
      />
    </div>
  )

  // The legend's slot depends on the variant; the ribbon is always the left rail.
  const slots: PdfViewerSlots = {
    left: ribbon,
    [preset.slot]:
      preset.slot === "right" ? (
        <div className="h-full overflow-auto border-l border-border bg-background px-2 py-4">
          {legend}
        </div>
      ) : (
        legend
      ),
  }

  return (
    <div className="flex min-h-0 min-w-0 flex-1 flex-col space-y-1.5">
      <div className="flex flex-wrap items-baseline gap-x-2">
        <span className="text-[11px] font-medium tracking-wide text-muted-foreground uppercase">
          {preset.label}
        </span>
        <code className="text-[11px] text-muted-foreground">
          variant=&quot;{preset.variant}&quot;
          {preset.orientation === "vertical" ? " · vertical" : ""}
        </code>
      </div>
      {/* The panel fills the remaining height (flex-1) and the page itself is
          held at A4 portrait (21/29.7), so its width is derived from that height
          and centered — never content-sized, which is what lets the `h-full`
          rails inside resolve. */}
      <div className="flex min-h-0 flex-1 justify-center">
        <div
          ref={panelRef}
          className="aspect-[21/29.7] h-full max-w-full overflow-hidden rounded-lg border bg-card"
        >
          <PdfViewer
            src={PDF_URL}
            bare
            toolbar={false}
            railToggle={false}
            downloadFileName="attention.pdf"
            slots={slots}
            onVisiblePageChange={setCurrentPage}
            className="h-full"
          />
        </div>
      </div>
    </div>
  )
}

"use client"

import * as React from "react"

import {
  getSegmentSurfaceProps,
  type SegmentInteraction,
} from "@/lib/segment-interaction"
import { type Segment } from "@/lib/segments"
import { cn } from "@/lib/utils"

/** How the legend attaches to the document surface. */
export type SegmentLegendVariant = "bar" | "floating" | "plain"
export type SegmentLegendOrientation = "horizontal" | "vertical"
export type SegmentLegendSide = "top" | "bottom" | "left" | "right"
export type SegmentLegendDensity = "comfortable" | "compact"

export interface SegmentLegendProps {
  segments: Segment[]
  /**
   * How the legend attaches to the document surface:
   * - `bar` — flush, full-width, bordered on its docking side (default).
   * - `floating` — an overlay card pinned to a corner; needs a `relative` parent.
   * - `plain` — raw entries, no chrome (compose your own container).
   * @default "bar"
   */
  variant?: SegmentLegendVariant
  /** Lay entries out horizontally (wrap/grid) or vertically (rail). @default "horizontal" */
  orientation?: SegmentLegendOrientation
  /** Edge the legend docks to — drives the border (`bar`) or anchor (`floating`). */
  side?: SegmentLegendSide
  /** Swatch + label scale. @default "comfortable" */
  density?: SegmentLegendDensity
  /** Shared hover/focus/selection state. */
  interaction?: SegmentInteraction
  /** Fired when a segment surface is clicked, after shared selection is requested. */
  onSelect?: (segment: Segment) => void
  /** 1-based current page; owning segments receive current-page styling. */
  currentPage?: number | null
  /** Lay entries out on a grid of N columns instead of wrapping inline (horizontal only). */
  columns?: number
  /** Render a "Show all / Hide unused" toggle when some segments own no pages. */
  showUnusedToggle?: boolean
  /** Controlled visibility of zero-page segments. */
  showUnused?: boolean
  /** Initial visibility of zero-page segments when `showUnused` is uncontrolled. */
  defaultShowUnused?: boolean
  onShowUnusedChange?: (showUnused: boolean) => void
  /** A muted caption rendered under the entries (e.g. a classification's reasoning). */
  caption?: React.ReactNode
  className?: string
}

const DENSITY = {
  comfortable: { swatch: "h-3 w-5", text: "text-xs", gap: "gap-x-4 gap-y-1.5" },
  compact: { swatch: "h-2.5 w-4", text: "text-[11px]", gap: "gap-x-3 gap-y-1" },
} as const

const DOCK_BORDER: Record<SegmentLegendSide, string> = {
  top: "border-b",
  bottom: "border-t",
  left: "border-r",
  right: "border-l",
}

const FLOAT_ANCHOR: Record<SegmentLegendSide, string> = {
  top: "absolute left-3 top-3",
  bottom: "absolute bottom-3 left-3",
  left: "absolute left-3 top-3",
  right: "absolute right-3 top-3",
}

/**
 * Compact color legend: one swatch + label per segment. Hovering, focusing, or
 * selecting highlights that segment and dims the others. Segments containing
 * `currentPage` receive separate current-page styling.
 * Zero-page segments are hidden unless shown via the toggle.
 *
 * `variant` controls how it sits on the document surface (flush bar, floating
 * overlay, or unstyled) so the same legend works for the classify, split, and
 * partition viewers without each one re-building its own chrome.
 */
export function SegmentLegend({
  segments,
  variant = "bar",
  orientation = "horizontal",
  side,
  density = "comfortable",
  interaction,
  onSelect,
  currentPage,
  columns,
  showUnusedToggle = false,
  showUnused,
  defaultShowUnused = false,
  onShowUnusedChange,
  caption,
  className,
}: SegmentLegendProps) {
  const [uncontrolledShowUnused, setUncontrolledShowUnused] =
    React.useState(defaultShowUnused)
  const reveal = showUnused ?? uncontrolledShowUnused
  const visible = reveal ? segments : segments.filter((s) => s.pages.length > 0)
  const hasHidden = segments.some((s) => s.pages.length === 0)

  if (visible.length === 0) return null

  const d = DENSITY[density]
  const dockSide = side ?? (orientation === "vertical" ? "left" : "top")
  const isVertical = orientation === "vertical"

  const chrome = {
    bar: cn("bg-background px-3 py-2", DOCK_BORDER[dockSide]),
    floating: cn(
      "z-10 rounded-lg border bg-background/90 px-3 py-2 shadow-md backdrop-blur",
      FLOAT_ANCHOR[dockSide]
    ),
    plain: "",
  }[variant]

  const toggleUnused = () => {
    const next = !reveal
    if (showUnused === undefined) {
      setUncontrolledShowUnused(next)
    }
    onShowUnusedChange?.(next)
  }

  return (
    <div
      data-slot="segment-legend"
      data-variant={variant}
      className={cn(chrome, className)}
    >
      <div
        className={cn(
          d.gap,
          isVertical
            ? "flex flex-col"
            : columns
              ? "grid"
              : "flex flex-wrap items-center"
        )}
        style={
          !isVertical && columns
            ? { gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` }
            : undefined
        }
      >
        {visible.map((segment) => {
          const { state, eventHandlers, ariaProps, dataProps } =
            getSegmentSurfaceProps({
              segment,
              interaction,
              currentPage,
              onSelect,
            })
          return (
            <button
              key={segment.id}
              type="button"
              {...ariaProps}
              {...dataProps}
              {...eventHandlers}
              title={segment.label}
              className={cn(
                "flex min-w-0 items-center gap-2 rounded-[3px] transition-opacity focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
                d.text,
                state.isDimmed ? "opacity-40" : "opacity-100"
              )}
            >
              <span
                aria-hidden
                className={cn("shrink-0 rounded-[2px]", d.swatch)}
                style={{ backgroundColor: segment.color }}
              />
              {/* Reserve the bold width up front: an always-semibold but
                  invisible copy sizes the slot, and the visible label overlays
                  it so highlighted/current labels cannot shift the layout. */}
              <span className="grid min-w-0">
                <span
                  aria-hidden
                  className="invisible col-start-1 row-start-1 truncate font-semibold"
                >
                  {segment.label}
                </span>
                <span
                  className={cn(
                    "col-start-1 row-start-1 truncate",
                    state.isHighlighted || state.isCurrent || state.isSelected
                      ? "font-semibold text-foreground"
                      : "font-normal text-muted-foreground"
                  )}
                >
                  {segment.label}
                </span>
              </span>
            </button>
          )
        })}
      </div>
      {showUnusedToggle && hasHidden ? (
        <button
          type="button"
          aria-label={
            reveal
              ? "Hide unused segments"
              : `Show ${segments.length - visible.length} unused segments`
          }
          onClick={toggleUnused}
          className="mt-2 text-[10px] font-medium text-muted-foreground underline-offset-2 hover:text-foreground hover:underline"
        >
          {reveal ? "Hide unused" : "Show all"}
        </button>
      ) : null}
      {caption ? (
        <div className="mt-1.5 line-clamp-2 text-xs leading-relaxed text-muted-foreground">
          {caption}
        </div>
      ) : null}
    </div>
  )
}
